import yaml
from pathlib import Path


def merge_yaml_files(file_paths: list[str], key: str) -> list[dict]:
    """Merge multiple YAML files on a common key column.

    Each file must contain a list of dicts, where every dict has the
    specified key. Later files override earlier ones for the same key.

    Args:
        file_paths: Paths to YAML files.
        key: The dictionary key used to match records across files.

    Returns:
        A list of merged dicts, sorted by key value.
    """
    merged: dict[str, dict] = {}

    for path in file_paths:
        with open(path) as f:
            records = yaml.safe_load(f)

        if not isinstance(records, list):
            raise ValueError(f"{path}: expected a list of dicts, got {type(records).__name__}")

        for record in records:
            if key not in record:
                raise ValueError(f"{path}: record missing key '{key}': {record}")
            record_key = str(record[key])
            if record_key in merged:
                merged[record_key].update(record)
            else:
                merged[record_key] = dict(record)

    return sorted(merged.values(), key=lambda r: r[key])
